\begin{document}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
trig format plots=rad,
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={draw=none},
axis line style = thick,
axis y line = center,
axis x line = middle,
%axis equal,
%grid = both,
xmin = -6.5,
xmax = 2.5,
ymin = -8.5,
ymax = 3.5,
xtick = {-3,1},
ytick = {-7,1},
%xticklabels = {,,},
%yticklabels = {,,},
%minor xtick={-10,-9,...,10},
%minor ytick={-10,-9,...,10},   
yticklabel style={xshift={(\tick==-7)*20pt}},
xticklabel style={yshift={(\tick==-3)*15pt}},
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above right},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]

% Graphics
\addplot [dotted, domain=-10:10,samples=300,color=red,line width=1pt, opacity=0.25]{2-x^2};
\addplot [domain=-3:1,samples=300,color=red,line width=1pt]{2-x^2};
\addplot [dashed, domain=-7:10,samples=300,color=black,line width=1pt]{-2};

