\draw[-, line width=0.5pt,dashed,opacity=0.5] (axis cs:0,-7) -- (axis cs:-3,-7) -- (axis cs:-3,0);
\draw[-, line width=0.5pt,dashed,opacity=0.5] (axis cs:0,1) -- (axis cs:1,1) -- (axis cs:1,0);
\draw[-, line width=1.2pt,blue] (axis cs:0,-7) -- (axis cs:0,1);
\draw[-, line width=1.2pt,blue] (axis cs:-3,0) -- (axis cs:1,0);
\node[circle,draw=none,fill=blue,inner sep=1.5pt] at (axis cs: -3,0) {};
\node[circle,draw=none,fill=blue,inner sep=1.5pt] at (axis cs: 1,0) {};
